n/// recommendation renders without a TMDB call — and still reads correctly years\n/// later if the artwork has since changed.\nmodel Recommendation {\n  id         String @id @default(cuid())\n  fromUserId String\n  fromUser   User   @relation(\"SentRecommendations\", fields: [fromUserId], references: [id], onDelete: Cascade)\n  toUserId   String\n  toUser     User   @relation(\"ReceivedRecommendations\", fields: [toUserId], references: [id], onDelete: Cascade)\n\n  /// \"movie\" | \"tv\"\n  mediaType String\n  tmdbId    Int\n  title     String\n  poster    String?\n  /// An optional line from the sender. Short on purpose — this is a nudge.\n  note      String?\n\n  createdAt   DateTime  @default(now())\n  /// When the recipient last saw it in their notifications.\n  seenAt      DateTime?\n  /// Set when they clear it, so it stops turning up without being deleted.\n  dismissedAt DateTime?\n\n  /// One standing recommendation per person per title: pressing it twice is the\n  /// same sentence said twice, not two separate suggestions.\n  @@unique([fromUserId, toUserId, mediaType, tmdbId])\n  @@index([toUserId, dismissedAt])\n}\n\n/// A viewing the user deleted that had come from a source carrying its own id.\n///\n/// Deleting a play removes the row, and with it the `sourceRef` that was the\n/// only evidence the sync had already seen that Plex history entry — so the next\n/// sync imported it again, ten minutes later, forever. This is the gravestone:\n/// `recordPlay` consults it before creating anything sourced, so \"I did not\n/// watch that\" survives a re-sync.\n///\n/// Deliberately permanent. Watching the thing again on Plex writes a *new*\n/// history entry with a new `viewedAt`, hence a new ref, which is not buried\n/// here — so a real rewatch still lands.\nmodel DeletedPlay {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  /// \"plex\" | \"trakt\" — matches `Play.source`.\n  source    String\n  sourceRef String\n  deletedAt DateTime @default(now())\n\n  @@unique([userId, source, sourceRef])\n}\n\n/// One row per pair, owned by whoever asked first. A pair is friends only once\n/// the addressee has accepted; until then the row is the outstanding request.\nmodel Friendship {\n  id          String    @id @default(cuid())\n  requesterId String\n  requester   User      @relation(\"SentFriendRequests\", fields: [requesterId], references: [id], onDelete: Cascade)\n  addresseeId String\n  addressee   User      @relation(\"ReceivedFriendRequests\", fields: [addresseeId], references: [id], onDelete: Cascade)\n  /// \"pending\" | \"accepted\"\n  status      String    @default(\"pending\")\n  createdAt   DateTime  @default(now())\n  respondedAt DateTime?\n\n  @@unique([requesterId, addresseeId])\n  @@index([addresseeId, status])\n  @@index([requesterId, status])\n}\n\n/// One row per episode a user has watched.\n///\n/// This and `WatchedMovie` are a uniqueness index over `Play` rather than a\n/// second record of what happened: they answer \"have I seen this\", while the\n/// play log answers \"how often, and when\". Only `src/lib/plays.ts` writes them.\nmodel WatchedEpisode {\n  id            String    @id @default(cuid())\n  userId        String\n  user          User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  showId        Int\n  showName      String\n  showPoster    String?\n  seasonNumber  Int\n  episodeNumber Int\n  episodeName   String\n  runtime       Int       @default(42)\n  /// The *first* time it was watched — the oldest play. Rewatches move\n  /// `lastWatchedAt` instead, so \"when did I discover this\" survives them.\n  watchedAt     DateTime  @default(now())\n  lastWatchedAt DateTime?\n  /// How many plays there are. Denormalised so the title page does not need a\n  /// GROUP BY, and a free drift check against COUNT(*) on the log.\n  plays         Int       @default(1)\n\n  @@unique([userId, showId, seasonNumber, episodeNumber])\n  @@index([userId, watchedAt])\n}\n\nmodel WatchedMovie {\n  id            String    @id @default(cuid())\n  userId        String\n  user          User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  movieId       Int\n  title         String\n  poster        String?\n  runtime       Int       @default(0)\n  /// TMDB audience score (0-100) captured when it was logged.\n  score         Int?\n  /// The first time it was watched. See `WatchedEpisode.watchedAt`.\n  watchedAt     DateTime  @default(now())\n  lastWatchedAt DateTime?\n  plays         Int       @default(1)\n\n  @@unique([userId, movieId])\n  @@index([userId, watchedAt])\n}\n\n/// One viewing. Append-only: the log of what was actually watched and when,\n/// which is what makes rewatches countable.\n///\n/// Everything that asks \"how much have I watched\" reads this; everything that\n/// asks \"have I seen it\" reads `WatchedMovie` / `WatchedEpisode`. Writes go\n/// through `recordPlay` in `src/lib/plays.ts` and nowhere else — that is what\n/// keeps the two in step.\nmodel Play {\n  id            String   @id @default(cuid())\n  userId        String\n  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  /// \"movie\" | \"tv\"\n  mediaType     String\n  /// The film's id, or the *show's* id for an episode.\n  tmdbId        Int\n  /// Film title, or show name. Denormalised so the log describes itself.\n  title         String\n  poster        String?\n  seasonNumber  Int?\n  episodeNumber Int?\n  episodeName   String?\n  runtime       Int      @default(0)\n  watchedAt     DateTime @default(now())\n  /// \"manual\" | \"plex\" | \"trakt\" | \"backfill\"\n  source        String   @default(\"manual\")\n  /// Stable id from whichever source reported it, where one exists. Plex play\n  /// history gives `${ratingKey}:${viewedAt}`; a manual tick has nothing, hence\n  /// null. SQLite treats nulls as distinct in a unique index, so the manual and\n  /// backfilled rows never collide with each other — only the sourced ones do,\n  /// which is exactly the deduplication wanted.\n  sourceRef     String?\n\n  @@unique([userId, source, sourceRef])\n  @@index([userId, watchedAt])\n  @@index([userId, mediaType, tmdbId, watchedAt])\n}\n\n/// A notification the user has dismissed.\n///\n/// Notifications themselves are *derived* rather than stored — an outstanding\n/// friend request is a pending `Friendship`, a new badge is an\n/// `UnlockedAchievement` — so the list can never disagree with reality: accept a\n/// request and its notification stops existing, with nothing to keep in step.\n/// The one thing that cannot be derived is whether it has been seen, which is\n/// all this table holds.\nmodel NotificationRead {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  /// `friend:<friendshipId>` or `badge:<achievementId>`.\n  key       String\n  readAt    DateTime @default(now())\n  /// Cleared away rather than merely seen. A read notification stays on the\n  /// list, greyed — a friend request you have read is still one you have not\n  /// answered — so \"clear\" is the separate, deliberate act of getting rid of it.\n  dismissed Boolean  @default(false)\n\n  @@unique([userId, key])\n  @@index([userId])\n}\n\n/// Something still meant to be watched.\nmodel WatchlistItem {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  mediaType String // \"movie\" | \"tv\"\n  tmdbId    Int\n  title     String\n  poster    String?\n  score     Int?\n  addedAt   DateTime @default(now())\n\n  /// Filled in lazily so the watchlist can be sorted by length and filtered by\n  /// what is streaming. Both go stale, hence the timestamp.\n  runtime      Int?\n  /// Comma-separated streaming provider names for the owner's region, or \"\"\n  /// when nothing streams it. Null means \"not looked up yet\".\n  streaming    String?\n  /// The same offers as TMDB provider ids. Names are what gets shown; ids are\n  /// what gets compared, because TMDB lists one service under several of them\n  /// and which one a title comes back under varies — see `KNOWN_PROVIDERS`.\n  streamingIds String?\n  enrichedAt   DateTime?\n\n  @@unique([userId, mediaType, tmdbId])\n}\n\n/// Something loved, as opposed to something queued.\n///\n/// Deliberately not a `MediaList`: the heart on a title page is one press with\n/// no list to choose, every user has exactly one of these, and it must never be\n/// renamed or deleted. A row of its own keeps that guarantee in the schema\n/// rather than in the code that reads it.\nmodel Favourite {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  mediaType String // \"movie\" | \"tv\"\n  tmdbId    Int\n  title     String\n  poster    String?\n  score     Int?\n  addedAt   DateTime @default(now())\n\n  @@unique([userId, mediaType, tmdbId])\n  @@index([userId, addedAt])\n}\n\n/// A list the user made: either one they fill by hand, or a standing question.\n///\n/// The watchlist and the favourites are *not* rows here — they are fixed parts\n/// of the app with their own tables, their own meaning and their own consumers\n/// (Plex sync reads the watchlist; the calendar and the quiz do too). This table\n/// is only for the lists a user invents, which is what makes deleting one safe.\nmodel MediaList {\n  id      String  @id @default(cuid())\n  userId  String\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name    String\n  /// \"manual\" — the user adds titles by hand.\n  /// \"smart\"  — the titles are whatever `filters` currently answers.\n  kind    String  @default(\"manual\")\n  /// The smart list's question, as JSON matching `SmartFilters` in\n  /// `src/lib/smart-filters.ts`. Null on a manual list. Stored as text because\n  /// nothing ever queries *into* it: it is read whole, parsed, and re-run.\n  filters String?\n\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  /// When a smart list's answers were last rebuilt from TMDB. Null means never,\n  /// which is also what a freshly edited list is set back to.\n  refreshedAt DateTime?\n\n  /// Ask Overseerr for what turns up on this list, without being told to.\n  ///\n  /// Off by default and deliberately opt-in per list: a standing question that\n  /// files requests on its own is the one feature here that spends somebody\n  /// else's disk, and \"top rated films of all time\" would ask for four hundred\n  /// of them.\n  autoRequest      Boolean   @default(false)\n  /// \"missing\" — skip anything already streaming on a service the user pays for.\n  /// \"all\"     — ask for everything the list answers with.\n  autoRequestScope String    @default(\"missing\")\n  /// How many titles one run may ask for. Capped again in code, because a\n  /// number in a database is not a promise.\n  autoRequestCap   Int       @default(5)\n  /// When a run last filed anything, for the panel to report.\n  autoRequestedAt  DateTime?\n\n  items MediaListItem[]\n\n  @@index([userId, createdAt])\n}\n\n/// One title on a list.\n///\n/// For a manual list this is the record — the only place that membership\n/// exists. For a smart list it is a cache of the last answer, thrown away and\n/// rewritten on every refresh, so that opening the list is a database read\n/// rather than a fan of TMDB requests.\nmodel MediaListItem {\n  id        String    @id @default(cuid())\n  listId    String\n  list      MediaList @relation(fields: [listId], references: [id], onDelete: Cascade)\n  mediaType String // \"movie\" | \"tv\"\n  tmdbId    Int\n  title     String\n  poster    String?\n  score     Int?\n  /// Release year as TMDB gives it, for the card caption. Text, because it is\n  /// only ever printed and TMDB leaves it blank on unannounced titles.\n  year      String?\n  /// Where it sits in the list: insertion order by hand, TMDB's own ranking on\n  /// a smart list. Sorting on this is what keeps \"best rated first\" meaningful\n  /// after the rows have been shuffled through the database.\n  position  Int       @default(0)\n  addedAt   DateTime  @default(now())\n\n  @@unique([listId, mediaType, tmdbId])\n  @@index([listId, position])\n}\n\n/// A thumbs up or down on a single episode. Separate from Rating, which is a\n/// percentage on a whole title — nobody wants to score an episode out of 100.\nmodel EpisodeRating {\n  id            String   @id @default(cuid())\n  userId        String\n  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  showId        Int\n  seasonNumber  Int\n  episodeNumber Int\n  liked         Boolean\n  updatedAt     DateTime @updatedAt\n\n  @@unique([userId, showId, seasonNumber, episodeNumber])\n  @@index([userId, showId])\n}\n\n/// A show the user has given up on. The watched episodes stay — this only says\n/// \"stop asking me about it\", so it drops out of Up next and the calendar.\nmodel DroppedShow {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  showId    Int\n  showName  String\n  createdAt DateTime @default(now())\n\n  @@unique([userId, showId])\n  @@index([userId])\n}\n\n/// One row per browser that has agreed to receive notifications. The keys are\n/// the browser's own, and are useless to anyone but its push service.\nmodel PushSubscription {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  /// Free text from the browser, so a user can tell their devices apart.\n  label     String?\n  createdAt DateTime @default(now())\n  /// Last date (YYYY-MM-DD) this device was told about, so a reminder is not\n  /// repeated if the job runs more than once a day.\n  lastSent  String?\n\n  @@index([userId])\n}\n\n/// An achievement a user has earned. Progress itself is always recomputed from\n/// the watch history — only the moment of earning is worth keeping, because it\n/// is the one thing that cannot be derived again later.\n///\n/// `key` is an id from the catalogue in `src/lib/achievements/catalogue.ts`.\n/// Rows for keys that no longer exist are ignored rather than deleted, so a\n/// renamed achievement does not throw away someone's history.\nmodel UnlockedAchievement {\n  id         String   @id @default(cuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  key        String\n  unlockedAt DateTime @default(now())\n  /// True when this badge came with an imported history rather than being earned\n  /// here: either it was already satisfied when the account's starting line was\n  /// drawn, or it was added to the catalogue later and a years-old history met it\n  /// on sight. The badge is kept and shown either way — it is a true statement\n  /// about what someone has watched — but it pays no XP towards the Trekker\n  /// level. It still counts towards the lifetime figure.\n  carried    Boolean  @default(false)\n\n  @@unique([userId, key])\n  @@index([userId])\n}\n\n/// A monthly challenge someone finished. One row per challenge per month, so a\n/// challenge that comes round again next year is a fresh thing to win.\n///\n/// Like `UnlockedAchievement`, only the moment is stored — the progress behind\n/// it is recomputed from that month's plays every time it is shown. The XP is\n/// written down because the reward is fixed when it is won: retuning a\n/// challenge later should not quietly restate what someone already earned.\nmodel ChallengeRun {\n  id          String   @id @default(cuid())\n  userId      String\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  /// Challenge id from `src/lib/challenges/catalogue.ts`.\n  key         String\n  /// The month it belongs to, as \"YYYY-MM\".\n  period      String\n  xp          Int\n  completedAt DateTime @default(now())\n\n  @@unique([userId, key, period])\n  @@index([userId, period])\n}\n\n/// Facts about a title that TMDB knows and we do not store on the watched rows:\n/// genres, language, release date, franchise. Shared by every user rather than\n/// copied per row, and refreshed only when it ages out — the achievements page\n/// asks about hundreds of titles at once and none of this moves.\nmodel TitleMeta {\n  id               String   @id @default(cuid())\n  mediaType        String // \"movie\" | \"tv\"\n  tmdbId           Int\n  title            String\n  /// Genre names, comma separated. Names rather than ids because TMDB numbers\n  /// film and television genres differently for the same idea.\n  genres           String\n  /// ISO 639-1, e.g. \"en\", \"ko\".\n  originalLanguage String?\n  /// YYYY-MM-DD: a film's release, a show's first air date.\n  releaseDate      String?\n  runtime          Int?\n  /// TMDB collection (\"belongs to\" franchise), films only.\n  collectionId     Int?\n  collectionName   String?\n  fetchedAt        DateTime @default(now())\n\n  @@unique([mediaType, tmdbId])\n}\n\nmodel Rating {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  mediaType String\n  tmdbId    Int\n  title     String\n  poster    String?\n  score     Int // 1-100 percentage\n  review    String?\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, mediaType, tmdbId])\n}\n",
